def solve(rows):
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 5 != 3 or i == len(rows) - 1:
            filtered_rows.append(row)

    if not filtered_rows:
        return 0

    rotated_rows = filtered_rows[1:] + [filtered_rows[0]]

    total_payable = 0
    for price, discount in rotated_rows:
        discount = min(discount, 8)
        price = max(0, price - discount)
        total_payable += price

    return total_payable
